mapper.select:
SELECT s.SUBJECT_ID as subjectId, s.SUBJECT_CODE as subjectCode, s.SUBJECT_NAME as subjectName, s.SUBJECT_LEVEL as subjectLevel, s.PARENT_SUBJECT_ID as parentSubjectId, p.SUBJECT_NAME as parentSubjectName, s.SUBJECT_TYPE as subjectType, s.BALANCE_DIRECTION as balanceDirection, s.IS_LEAF as isLeaf, s.IS_ENABLED as isEnabled, s.IS_CASH as isCash, s.IS_BANK as isBank, s.AUXILIARY_TYPES as auxiliaryTypes, s.BOOK_ID as bookId, s.TENANT_ID as tenantId, s.VERSION as version, s.CREATE_TIME as createTime, s.UPDATE_TIME as updateTime, s.CREATOR as creator, s.UPDATER as updater FROM TBL_ACCOUNT_SUBJECT s LEFT JOIN TBL_ACCOUNT_SUBJECT p ON s.PARENT_SUBJECT_ID = p.SUBJECT_ID AND p.IS_DELETED = 0 WHERE s.IS_DELETED = 0
AND s.BOOK_ID = #{param.bookId}
AND s.TENANT_ID = #{param.tenantId}
AND s.SUBJECT_CODE LIKE '%' || #{param.subjectCode} || '%'
AND s.SUBJECT_NAME LIKE '%' || #{param.subjectName} || '%'
AND s.SUBJECT_TYPE = #{param.subjectType}
AND s.SUBJECT_LEVEL = #{param.subjectLevel}
AND s.PARENT_SUBJECT_ID = #{param.parentSubjectId}
AND s.IS_LEAF = #{param.isLeaf}
AND s.BALANCE_DIRECTION = #{param.balanceDirection}
AND s.IS_ENABLED = #{param.isEnabled}
ORDER BY s.SUBJECT_CODE ASC

SELECT * FROM TBL_ACCOUNT_SUBJECT 
WHERE IS_DELETED = 0 
AND SUBJECT_CODE = #{subjectCode}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}

    AND SUBJECT_ID != #{excludeId}

AND ROWNUM = 1

SELECT SUBJECT_ID as subjectId, SUBJECT_CODE as subjectCode, SUBJECT_NAME as subjectName, SUBJECT_LEVEL as subjectLevel, PARENT_SUBJECT_ID as parentSubjectId, SUBJECT_TYPE as subjectType, BALANCE_DIRECTION as balanceDirection, IS_LEAF as isLeaf, IS_ENABLED as isEnabled, IS_CASH as isCash, IS_BANK as isBank, AUXILIARY_TYPES as auxiliaryTypes, BOOK_ID as bookId, TENANT_ID as tenantId, VERSION as version, CREATE_TIME as createTime, UPDATE_TIME as updateTime, CREATOR as creator, UPDATER as updater FROM TBL_ACCOUNT_SUBJECT WHERE IS_DELETED = 0 AND BOOK_ID = #{bookId} AND TENANT_ID = #{tenantId}
AND PARENT_SUBJECT_ID = #{parentSubjectId}
AND PARENT_SUBJECT_ID IS NULL
ORDER BY SUBJECT_CODE ASC

